# Run at repository root; no source data or estimates are generated by Arboris.
suppressPackageStartupMessages({library(survival); library(jsonlite)})
root <- 'tests/fixtures/agent_completion/survival'
original <- 'tests/fixtures/v186_families/families.csv'
d <- read.csv(original)
tied <- d
tied$duration <- pmax(0.1, round(tied$duration * 2)/2)
write.csv(tied, file.path(root, 'tied.csv'), row.names=FALSE)
one <- function(path, ties) {
  d <- read.csv(path)
  fit <- coxph(Surv(duration,event) ~ x1 + x2 + grp, data=d, ties=ties,
               x=TRUE, y=TRUE, control=coxph.control(eps=1e-12, toler.chol=1e-14))
  z <- cox.zph(fit, transform='log', terms=FALSE)
  tests <- lapply(seq_len(nrow(z$table)), function(i) list(statistic=z$table[i,1], df=z$table[i,2],p_value=z$table[i,3]))
  names(tests) <- c('x1','x2','grp','global')
  list(source=path, ties=ties, tests=tests, coefficients=as.list(coef(fit)), nobs=nrow(d), n_events=sum(d$event))
}
out <- list(environment=list(R=R.version.string,survival=as.character(packageVersion('survival'))),
  command='LC_ALL=en_US.UTF-8 LANG=en_US.UTF-8 Rscript tests/fixtures/agent_completion/survival/generate_ph_reference.R',
  definition='Native survival::cox.zph(transform=log, terms=FALSE); chi-square score tests with beta nuisance information',
  tolerance=list(rtol=1e-7,atol=1e-9),
  cases=list(untied_breslow=one(original,'breslow'),untied_efron=one(original,'efron'),
             tied_breslow=one(file.path(root,'tied.csv'),'breslow'),tied_efron=one(file.path(root,'tied.csv'),'efron')))
writeLines(toJSON(out,auto_unbox=TRUE,pretty=TRUE,digits=NA),file.path(root,'ph_reference_r.json'))
